  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --surface: #121a2d;
        --surface-2: #182238;
        --border: #2c3b5c;
        --text: #e8eefc;
        --muted: #a7b4d4;
        --accent: #7c9cff;
        --accent-strong: #9bb2ff;
        --success: #44c48a;
        --error: #ff7c8b;
        --shadow: 0 24px 60px #00000066;
      }

      * {
        box-sizing: border-box;
      }

      html {
        min-height: 100%;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top, #1b2a52 0%, transparent 42%),
          linear-gradient(180deg, #09101e 0%, var(--bg) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        transform: translateY(-200%);
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--accent);
        color: #08101e;
        font-weight: 700;
        text-decoration: none;
        z-index: 10;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 4rem 1rem;
      }

      .card {
        width: min(100%, 34rem);
        padding: 2rem;
        border: 1px solid color-mix(in srgb, var(--border) 85%, white 15%);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, rgba(24, 34, 56, 0.96), rgba(14, 20, 35, 0.98));
        box-shadow: var(--shadow);
      }

      h1 {
        margin: 0 0 0.75rem;
        font-size: clamp(1.7rem, 4vw, 2.2rem);
        line-height: 1.15;
      }

      .intro {
        margin: 0 0 1.75rem;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 1.15rem;
        background: var(--surface);
      }

      fieldset {
        margin: 0;
        padding: 0;
        border: 0;
        min-inline-size: 0;
      }

      legend {
        padding: 0;
        margin: 0 0 1rem;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .required {
        color: var(--accent-strong);
      }

      .help-text {
        margin: -0.5rem 0 1rem;
        color: var(--muted);
        line-height: 1.5;
      }

      .options {
        display: grid;
        gap: 0.75rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.85rem;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        background: var(--surface-2);
        cursor: pointer;
        transition: border-color 160ms ease, transform 160ms ease, background-color 160ms ease;
      }

      .option:hover {
        border-color: color-mix(in srgb, var(--accent) 55%, var(--border));
        transform: translateY(-1px);
      }

      .option input {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0;
        accent-color: var(--accent);
      }

      .option span {
        line-height: 1.35;
      }

      .option input:focus-visible {
        outline: 3px solid var(--accent-strong);
        outline-offset: 3px;
      }

      .option:has(input:focus-visible) {
        border-color: var(--accent-strong);
      }

      .actions {
        display: flex;
        justify-content: flex-start;
      }

      button {
        appearance: none;
        border: 1px solid color-mix(in srgb, var(--accent) 70%, white 30%);
        border-radius: 0.95rem;
        padding: 0.9rem 1.2rem;
        background: linear-gradient(180deg, var(--accent-strong), var(--accent));
        color: #071021;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 10px 20px #00000040;
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible {
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        line-height: 1.5;
      }

      .status--success {
        color: var(--success);
      }

      .status--error {
        color: var(--error);
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
          border-radius: 1.15rem;
        }

        .form-field {
          padding: 1rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --border: ButtonBorder;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: Highlight;
          --accent-strong: Highlight;
          --success: CanvasText;
          --error: CanvasText;
        }

        .skip-link,
        .card,
        .form-field,
        .option,
        button {
          forced-color-adjust: auto;
        }

        .option input {
          accent-color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification Preferences</h1>
        <p class="intro">Choose the channel you want us to use for notifications.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help notification-status" aria-required="true">
              <legend>
                How do you prefer to receive notifications?
                <span class="required" aria-hidden="true"> *</span>
              </legend>
              <p class="help-text" id="notification-help">Select one answer before continuing.</p>

              <div class="options">
                <label class="option" for="email">
                  <input id="email" name="notification-method" type="radio" value="Email" required />
                  <span>Email</span>
                </label>
                <label class="option" for="sms">
                  <input id="sms" name="notification-method" type="radio" value="SMS" />
                  <span>SMS</span>
                </label>
                <label class="option" for="push">
                  <input id="push" name="notification-method" type="radio" value="Push Notifications" />
                  <span>Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit</button>
          </div>

          <p class="status" id="notification-status" aria-live="polite" aria-atomic="true"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("notification-status");
      const radios = Array.from(form.querySelectorAll('input[name="notification-method"]'));

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = form.querySelector('input[name="notification-method"]:checked');

        if (!selected) {
          radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
          status.className = "status status--error";
          status.textContent = "Choose Email, SMS, or Push Notifications to continue.";
          radios[0].focus();
          return;
        }

        radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
        status.className = "status status--success";
        status.textContent = `Saved preference: ${selected.value}.`;
      });

      radios.forEach((radio) => {
        radio.addEventListener("change", () => {
          radios.forEach((item) => item.removeAttribute("aria-invalid"));
          if (status.classList.contains("status--error")) {
            status.className = "status";
            status.textContent = "";
          }
        });
      });
    </script>
  </body>
</html>
