        color: #071021;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 10px 20px #00000040;
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible {
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        line-height: 1.5;
      }

      .status--success {
        color: var(--success);
      }

      .status--error {
        color: var(--error);
      }

      @media (max-width: 480px) {
        .card {
          padding: 1.25rem;
          border-radius: 1.15rem;
        }

        .form-field {
          padding: 1rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-2: Canvas;
          --border: ButtonBorder;
          --text: CanvasText;
          --muted: CanvasText;
          --accent: Highlight;
          --accent-strong: Highlight;
          --success: CanvasText;
          --error: CanvasText;
        }

        .skip-link,
        .card,
        .form-field,
        .option,
        button {
          forced-color-adjust: auto;
        }

        .option input {
          accent-color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <h1 id="page-title">Notification Preferences</h1>
        <p class="intro">Choose the channel you want us to use for notifications.</p>

        <form id="notification-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="notification-help notification-status" aria-required="true">
              <legend>
                How do you prefer to receive notifications?
                <span class="required" aria-hidden="true"> *</span>
              </legend>
              <p class="help-text" id="notification-help">Select one answer before continuing.</p>

              <div class="options">
                <label class="option" for="email">
                  <input id="email" name="notification-method" type="radio" value="Email" required />
                  <span>Email</span>
                </label>
                <label class="option" for="sms">
                  <input id="sms" name="notification-method" type="radio" value="SMS" />
                  <span>SMS</span>
                </label>
                <label class="option" for="push">
                  <input id="push" name="notification-method" type="radio" value="Push Notifications" />
                  <span>Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit</button>
          </div>

          <p class="status" id="notification-status" aria-live="polite" aria-atomic="true"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("notification-status");
      const radios = Array.from(form.querySelectorAll('input[name="notification-method"]'));

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = form.querySelector('input[name="notification-method"]:checked');

        if (!selected) {
          radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
          status.className = "status status--error";
          status.textContent = "Choose Email, SMS, or Push Notifications to continue.";
          radios[0].focus();
          return;
        }

        radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
        status.className = "status status--success";
        status.textContent = `Saved preference: ${selected.value}.`;
      });

      radios.forEach((radio) => {
        radio.addEventListener("change", () => {
          radios.forEach((item) => item.removeAttribute("aria-invalid"));
          if (status.classList.contains("status--error")) {
            status.className = "status";
            status.textContent = "";
          }
        });
      });
    </script>
  </body>
</html>
